'use client';
import { useForm } from 'react-hook-form';

type FormData = { email: string; password: string };

export default function LoginForm() {
  const { register, handleSubmit, formState: { errors } } = useForm<FormData>();
  return (
    <form onSubmit={handleSubmit((d) => console.log(d))} className="space-y-3">
      <input {...register('email', { required: true })} className="border rounded px-3 py-2 w-full" />
      {errors.email && <p className="text-red-500 text-sm">Required</p>}
      <input type="password" {...register('password', { required: true, minLength: 6 })} className="border rounded px-3 py-2 w-full" />
      <button className="bg-indigo-600 text-white px-4 py-2 rounded">{{submit_label}}</button>
    </form>
  );
}
